#!/usr/bin/env bash
# Builds roles/all.txt: every role list in one file, so the Scuffed world downloads
# all roles with ONE string load (VRChat only does one every 5 seconds).
#
# Each list becomes a section headed "### FILE: <file name>". The world matches a
# role to its section by the last part of that role's own link (e.g. devs.txt,
# "Com Lead"), so adding a new role file here needs no change to this script.
set -euo pipefail
cd "$(dirname "$0")/../.."

out=roles/all.txt
tmp=$(mktemp)
{
  echo "# AUTO-GENERATED - do not edit this file."
  echo "# Built from the other files in roles/ by .github/workflows/combine-roles.yml."
  echo "# Edit the individual role files instead; this one updates itself a minute later."
  for f in roles/*; do
    name=$(basename "$f")
    [ -f "$f" ] || continue
    [ "$name" = "all.txt" ] && continue
    echo
    echo "### FILE: $name"
    # Drop CRs and blank lines; make sure the last name ends with a newline.
    tr -d '\r' < "$f" | sed -e '/^[[:space:]]*$/d' -e '$a\'
  done
} > "$tmp"
mv "$tmp" "$out"
echo "Wrote $out"
